{
  "title": "The Mirror's Bridge",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara spreads a map of the ruined city on a fallen pillar.",
      "visual_description": "Dawn light filters through shattered arches as Mara unrolls a cracked parchment map, her brass compass glinting.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The glass diver adjusts his helmet before a broken window.",
      "visual_description": "Reflections of twisted spires dance in the curved glass of the diver's helmet as he checks its seal.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning about the castle gates.",
      "visual_description": "Inside a dark alley, the lamp's single eye glows amber as it whispers, its flame casting long shadows.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scurries through rubble toward the first gate.",
      "visual_description": "The small metal fox winds its tail, blue eyes scanning as it leaps over fallen stones and twisted iron.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "At the castle gates, armored figures pace in formation.",
      "visual_description": "Two figures in dented plate armor march back and forth before a massive iron gate, torches hissing in brackets.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The oracle lamp reveals a hidden side passage.",
      "visual_description": "The lamp's flame bends sideways, illuminating a mossy arch half-hidden behind a collapsed statue.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Inside a cursed tower, the sleeping tax collector snores on a throne of ledgers.",
      "visual_description": "Stamped papers stick to his sleeves as he sleeps, a pile of coin ledgers forming his pillow.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver swims through a mirror into the tower's upper room.",
      "visual_description": "The diver's form ripples as he emerges from a full-length mirror, water dripping onto dusty flagstones.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "Mara consults the oracle lamp about the rumors of a great beast.",
      "visual_description": "The lamp's flame pulses rapidly as Mara traces a faded symbol on her map with ink-stained fingers.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The tin fox discovers old royal banners draped from a balcony.",
      "visual_description": "Frayed crimson and gold cloth hang from a crumbling balcony, their emblems almost erased by weather.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Frightened townspeople huddle behind a barricade of carts.",
      "visual_description": "A dozen figures press together behind overturned wagons, their eyes wide at every distant clank.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp warns of a patrol approaching the square.",
      "visual_description": "The lamp's glow dims as it whispers urgently, Mara folding her map and motioning for silence.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Armored patrols march through the square, their footsteps echoing.",
      "visual_description": "Four figures in dented plate stride in lockstep, their torchlight glinting off scratched breastplates.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver leads the frightened townspeople through a mirror door.",
      "visual_description": "One by one, the figures step through a shimmering pane wedged in a ruined arch, vanishing into its depths.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Mara finds a magic door that opens only when she draws on it.",
      "visual_description": "She presses her ink-stained palm against the door's surface, and glowing lines spread like roots from her touch.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The tin fox triggers a trap on the bridge, alerting the patrols.",
      "visual_description": "A metal tripwire snaps, sending a bell clanging into the night as armored figures turn toward the sound.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across the bridge as the oracle lamp casts a smoke screen.",
      "visual_description": "Thick grey smoke pours from the lamp, obscuring the bridge as figures dash over broken cobbles.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the misty forest as the ruins fade behind them.",
      "visual_description": "The last mirror shatters on the bridge as the group disappears among fog-shrouded trees, the city lights growing distant.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

